class Notizbuch:
    def __init__(self, dateiname):
        self.dateiname = dateiname

    def schreibe(self, text):
        with open(self.dateiname, "w") as datei:
            datei.write(text)

    def lies(self):
        with open(self.dateiname, "r") as datei:
            return datei.read()

buch = Notizbuch("notiz.txt")
buch.schreibe("Nicht vergessen!")
print(buch.lies())
